import{_ as t,o as r,c as a,a2 as o}from"./chunks/framework.CdvW4CUT.js";const h=JSON.parse('{"title":"About CX","description":"","frontmatter":{"head":[["link",{"rel":"canonical","href":"https://cx-pl.io/project/"}],["meta",{"property":"og:url","content":"https://cx-pl.io/project/"}]]},"headers":[],"relativePath":"project/index.md","filePath":"project/index.md","lastUpdated":null}'),i={name:"project/index.md"};function n(s,e,l,c,p,d){return r(),a("div",null,[...e[0]||(e[0]=[o('<h1 id="about-cx" tabindex="-1">About CX <a class="header-anchor" href="#about-cx" aria-label="Permalink to &quot;About CX&quot;">​</a></h1><p>CX is an experimental programming language and native compiler project. Its compiler is written in C# and emits C and CMake build files. The standard library and runtime are implemented in C and CX. Current development also includes a package manager and Visual Studio Code support.</p><p>The language, runtime ABI, libraries, and tooling are changing. The project does not promise binary compatibility, and some features or platform paths are incomplete. Use the <a href="/project/revisions.html">tested revisions</a> and the repository documentation when evaluating a feature.</p><p>Reference documents and the syntax grammar are reproduced from repositories under their respective licenses. See <a href="/project/attributions.html">source license notices</a>.</p><h2 id="contributing" tabindex="-1">Contributing <a class="header-anchor" href="#contributing" aria-label="Permalink to &quot;Contributing&quot;">​</a></h2><p>The compiler, runtime, examples, package manager, and editor extension live in separate repositories in the <a href="https://github.com/cx-pl" target="_blank" rel="noreferrer">cx-pl GitHub organization</a>. Open issues or pull requests in the repository that owns the code or documentation. Include the CX, runtime, operating system, and native toolchain revisions when reporting a build or runtime issue.</p><h2 id="project-repositories" tabindex="-1">Project repositories <a class="header-anchor" href="#project-repositories" aria-label="Permalink to &quot;Project repositories&quot;">​</a></h2><ul><li><a href="https://github.com/cx-pl/cxc" target="_blank" rel="noreferrer">Compiler (<code>cxc</code>)</a></li><li><a href="https://github.com/cx-pl/cxcore" target="_blank" rel="noreferrer">Runtime and standard library (<code>cxcore</code>)</a></li><li><a href="https://github.com/cx-pl/examples" target="_blank" rel="noreferrer">Examples</a></li><li><a href="https://github.com/cx-pl/cxpm" target="_blank" rel="noreferrer">Package manager (<code>cxpm</code>)</a></li><li><a href="https://github.com/cx-pl/vscode-extension" target="_blank" rel="noreferrer">Visual Studio Code extension</a></li></ul>',8)])])}const m=t(i,[["render",n]]);export{h as __pageData,m as default};
